import React, { useEffect, useMemo, useState } from 'react';
import { Card, Table, Tag, Switch, Typography, Space, message, Tooltip, Spin } from 'antd';
import { apiRequest, buildAuthHeaders } from '../api';

type FormEntry = {
  id: string | number;
  key: string;
  name: string;
  category: 'U' | 'A' | 'F' | 'S' | 'H';
  route: string;
  roles: string[];
  enabled: boolean;
  owner?: string;
  status?: 'draft' | 'ready';
  desc?: string;
  row_version?: string | number;
  etag?: string;
};

const roleColor = (role: string): string => {
  switch (role) {
    case 'architect': return 'gold';
    case 'admin': return 'red';
    case 'vip': return 'purple';
    case 'premium': return 'blue';
    default: return 'default';
  }
};

const categoryLabel: Record<FormEntry['category'], string> = {
  U: 'Пользовательская',
  A: 'Аналитика',
  F: 'Функциональная',
  S: 'Настройки',
  H: 'Вспомогательная',
};

const UIFormsRegistry: React.FC = () => {
  const [forms, setForms] = useState<FormEntry[]>([]);
  const [loading, setLoading] = useState<boolean>(false);

  const allRoles = useMemo(() => {
    const set = new Set<string>();
    forms.forEach(f => (f.roles || []).forEach(r => set.add(r)));
    // Обязательные колоноки для RBAC-грида
    ['architect', 'admin'].forEach(r => set.add(r));
    return Array.from(set).sort();
  }, [forms]);

  const fetchForms = async () => {
    setLoading(true);
    try {
      const cfgHeaders = buildAuthHeaders();
      // Новый фасад P23/P22
      let data = null as any;
      try {
        data = await apiRequest('/api/ui/forms', 'GET', null, cfgHeaders as any);
      } catch {
        // Фолбек на старый путь, если фасад ещё не подключен
        data = await apiRequest('/api/admin/ui/forms', 'GET', null, cfgHeaders as any);
      }
      const items: FormEntry[] = Array.isArray(data?.items) ? data.items : Array.isArray(data) ? data : [];
      setForms(items);
    } catch (e) {
      message.error('Не удалось загрузить реестр форм');
      // eslint-disable-next-line no-console
      console.error('[UIFormsRegistry] load error', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchForms(); }, []);

  const toggleVisibility = async (formKey: string, role: string, visible: boolean) => {
    try {
      const body = { role, visible } as any;
      const headers: Record<string,string> = { ...buildAuthHeaders() as any };

      const current = forms.find(f => f.key === formKey);
      const ifMatch = (current?.etag || current?.row_version) ? String(current?.etag || current?.row_version) : '';
      if (ifMatch) headers['If-Match'] = ifMatch;

      const res = await fetch(`/api/ui/forms/${encodeURIComponent(formKey)}/visibility`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...headers },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const t = await res.text();
        throw new Error(`${res.status} ${res.statusText} ${t}`);
      }
      message.success('Сохранено');
      await fetchForms();
    } catch (e) {
      message.error('Ошибка сохранения');
      // eslint-disable-next-line no-console
      console.error('[UIFormsRegistry] save error', e);
    }
  };

  const columns = [
    {
      title: 'Ключ',
      dataIndex: 'key',
      key: 'key',
      width: 180,
      render: (v: string) => <Typography.Text code>{v}</Typography.Text>,
    },
    {
      title: 'Название',
      dataIndex: 'name',
      key: 'name',
      width: 220,
      render: (v: string, r: FormEntry) => (
        <div>
          <div style={{fontWeight:600}}>{v}</div>
          <div style={{fontSize:12, opacity:0.75}}>{r.desc}</div>
        </div>
      ),
    },
    {
      title: 'Категория',
      dataIndex: 'category',
      key: 'category',
      width: 140,
      render: (c: FormEntry['category']) => <Tag>{categoryLabel[c] || c}</Tag>,
    },
    {
      title: 'Маршрут',
      dataIndex: 'route',
      key: 'route',
      width: 220,
      render: (p: string) => <Typography.Text>{p}</Typography.Text>,
    },
    ...allRoles.map(role => ({
      title: role,
      key: `role_${role}`,
      width: 110,
      align: 'center' as const,
      render: (_: any, record: FormEntry) => {
        const visible = (record.roles || []).includes(role);
        return (
          <Switch
            checked={visible}
            size="small"
            onChange={(v) => toggleVisibility(record.key, role, v)}
          />
        );
      }
    })),
    {
      title: 'Статус',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      render: (s: FormEntry['status']) => (
        <Tag color={s === 'ready' ? 'green' : 'orange'}>{s || 'draft'}</Tag>
      )
    },
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-lg)' }}>
      <Card title="Реестр форм (Роли × Формы)" extra={loading ? <Spin size="small" /> : null}>
        <Table
          rowKey={(r) => String(r.key)}
          columns={columns as any}
          dataSource={forms}
          pagination={{ pageSize: 10, showSizeChanger: true, pageSizeOptions: [10,20,50,100] as any }}
          scroll={{ x: true }}
          size="middle"
        />
      </Card>
    </div>
  );
};

export default UIFormsRegistry;


